array.string:
export PATH="$HOME/.local/bin:/usr/local/bin:/opt/homebrew/bin:$PATH";
cd /Users/tm/Projects/Claude/ResearchMan;
LOG=$HOME/Library/Logs/researchman-exhibition.log;
[ -f $LOG ] && [ $(stat -f%z $LOG) -gt 5242880 ] && mv $LOG $LOG.1;
node scripts/run-if-due.mjs --state .last-exhibition-research-run.txt --daily-at 10 --minute 30 >> $LOG 2>&1 || exit 0;
# Case Study側(autoresearch)と同時発火した際のgit競合を防ぐ排他ロック（最大30分待ち）。
# ロックが90分超残存していたらkill -9等の残骸とみなし奪取する（3ジョブ合計でも90分あれば完走する）
LOCK=/tmp/researchman-git.lock; waited=0;
while ! mkdir $LOCK 2>/dev/null; do
  if [ -d $LOCK ] && [ $(( $(date +%s) - $(stat -f %m $LOCK) )) -gt 5400 ]; then
    echo "staleロック奪取: $(date)" >> $LOG; rmdir $LOCK 2>/dev/null; continue;
  fi;
  sleep 30; waited=$((waited+30));
  [ $waited -ge 1800 ] && { echo "ロック取得タイムアウト: $(date)" >> $LOG; exit 0; };
done;
trap "rmdir $LOCK 2>/dev/null" EXIT;
echo "===== Exhibition run start: $(date) =====" >> $LOG;
if ! node scripts/auto-research-exhibition.mjs >> $LOG 2>&1; then
  echo "収集エラー終了（作業ツリーを復元）: $(date)" >> $LOG;
  git checkout -- data/exhibition.json >> $LOG 2>&1;
  git clean -fd public/thumbnails/exhibition >> $LOG 2>&1;
  node scripts/run-if-due.mjs --state .last-exhibition-research-run.txt --mark >> $LOG 2>&1;
  node scripts/notify-line.mjs --result error --route exhibition --label Exhibition >> $LOG 2>&1;
  exit 0;
fi;
# commit 前に pre-push と同じ監査。FAIL を commit すると push が全滞留するため、戻して commit せずエラー通知
if ! node scripts/audit-exhibition.mjs >> $LOG 2>&1; then
  echo "audit-exhibition FAIL → 復元して commit しない: $(date)" >> $LOG;
  git checkout -- data/exhibition.json >> $LOG 2>&1;
  git clean -fd public/thumbnails/exhibition >> $LOG 2>&1;
  node scripts/run-if-due.mjs --state .last-exhibition-research-run.txt --mark >> $LOG 2>&1;
  node scripts/notify-line.mjs --result error --route exhibition --label Exhibition >> $LOG 2>&1;
  exit 0;
fi;
git add data/exhibition.json public/thumbnails/exhibition/ >> $LOG 2>&1;
if git diff --cached --quiet; then
  echo "変更なし（新規展覧会なし）: $(date)" >> $LOG;
  node scripts/notify-line.mjs --summary /tmp/researchman-exhibition-last-add.json --route exhibition --label Exhibition >> $LOG 2>&1;
else
  git commit -m "Exhibition radar: $(date '+%Y-%m-%d')" >> $LOG 2>&1;
  if git push >> $LOG 2>&1; then
    if node scripts/verify-deploy.mjs --skip-pages >> $LOG 2>&1 && node scripts/verify-exhibition-pages.mjs >> $LOG 2>&1; then
      echo "反映まで確認OK: $(date)" >> $LOG;
      node scripts/notify-line.mjs --summary /tmp/researchman-exhibition-last-add.json --route exhibition --label Exhibition >> $LOG 2>&1;
    else
      echo "push成功だが反映未確認（時間切れ）: $(date)" >> $LOG;
      # 0件追加の回は routine（追加ありは従来どおり critical）
      if node -e "const s=JSON.parse(require('fs').readFileSync('/tmp/researchman-exhibition-last-add.json','utf8'));process.exit((s.cases||[]).length?1:0)" 2>/dev/null; then PRI=routine; else PRI=critical; fi;
      node scripts/notify-line.mjs --result unverified --summary /tmp/researchman-exhibition-last-add.json --route exhibition --label Exhibition --priority $PRI >> $LOG 2>&1;
    fi;
  else
    echo "push失敗（pre-push監査で中止の可能性）。コミットはローカル残存。要手動対応: $(date)" >> $LOG;
    node scripts/notify-line.mjs --result pushfail --summary /tmp/researchman-exhibition-last-add.json --route exhibition --label Exhibition >> $LOG 2>&1;
  fi;
fi;
echo "Exhibition completed: $(date)" >> $LOG
